export const sites: Site[] = baseSites.map((site) => {
  const addition = rich[site.id] || {};
  const coreChapters = addition.chapters || supplementalStories[site.id] || [
    { title: "这处地址的历史起点", text: site.story },
    { title: "人物与事件怎样在此交汇", text: site.people.length ? `${site.people.join("、")}等人的经历，使这处门牌进入上海民盟的历史网络。人物的职业、组织关系和公共行动，需要放回${site.year}前后的城市环境中理解。` : `这处空间的功能变化与上海的产业、文化或组织发展相互交织。它的意义不止在建筑外观，更在于人在这里开展的公共活动。` },
    { title: "从现场继续追问", text: site.anchor },
    { title: "它与整部盟史的联系", text: `把${site.name}与同一人物、同一事件及相邻地址对照阅读，可以看到一处现场如何连接教育救国、民主运动、组织建设或参政履职。门牌是入口，完整历史来自人物、文献与城市空间的相互印证。` },
  ];
  const researchedChapters = deepResearchStories[site.id] || [];
  const canonicalChapters = researchedChapters.length >= 6
    ? researchedChapters
    : [...researchedChapters, ...coreChapters.filter((chapter) =>
      !researchedChapters.some((researched) => researched.title === chapter.title || researched.text === chapter.text))];
  const secondaryCategories: Partial<Record<string, SiteCategory[]>> = {
    nanhai: ["组织与机关"],
    "bund-15": ["英烈纪念"],
  };
  return {
    ...site,
    secondaryCategories: secondaryCategories[site.id] || site.secondaryCategories,
    ...(baseImages[site.id] || {}),
    chapters: canonicalChapters,
    facts: addition.facts || [site.year, `${site.district} · ${site.address}`, ...site.people.slice(0, 2)],
    architecture: architecture[site.id],
  };
});

